with remaining_keys as (select brand, category from products intersect all select brand, category from products where brand = 'Globex'), reconciled as (select s.* from products s inner join remaining_keys k on s.brand = k.brand and s.category = k.category) select case when price >= 1080 then 'LARGE' else 'SMALL' end as price_tier, case when stock_qty >= 350 then 'LARGE' else 'SMALL' end as stock_qty_tier, count(distinct brand) as distinct_brands, round(sum(cost) / nullif(count(case when category = 'Sports' then 1 end), 0), 2) as cost_per_sports, count(*) as cnt, grouping(case when price >= 1080 then 'LARGE' else 'SMALL' end) as grouping_level from reconciled group by grouping sets ((case when price >= 1080 then 'LARGE' else 'SMALL' end, case when stock_qty >= 350 then 'LARGE' else 'SMALL' end), (case when price >= 1080 then 'LARGE' else 'SMALL' end)) order by distinct_brands nulls last;
